package vn.smartfarm.iot.irrigation;
import com.fasterxml.jackson.databind.*;
import java.sql.Timestamp;import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.PlatformTransactionManager;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.irrigation.queue-schedule-enabled=true","smartfarm.irrigation.queue-schedule-initial-delay-ms=3600000","smartfarm.irrigation-queue.scheduling-enabled=false"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class ZoneQueueScheduleTest {
 @Autowired ZoneQueueSchedule schedules;@Autowired IrrigationQueue queue;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;@Autowired PlatformTransactionManager manager;
 @Autowired org.springframework.context.ApplicationContext context;
 final Instant due=Instant.parse("2026-10-22T23:00:00Z"); // Friday 06:00 Vietnam
 String before;
 @BeforeEach void setup(){cleanup();jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('SQSOIL','Soil','AREA001','SOIL',2),('SQSOIL2','Soil2','AREA001','SOIL',2),('SQWATER','Water','AREA001','WATER',2)");
  for(var node:List.of("SQSOIL","SQSOIL2"))for(int n=1;n<=3;n++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')",node,"SOIL"+n);
  jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('SQWATER','LOW','WATER_PRESENT','boolean'),('SQWATER','FLOW','FLOW_RATE','L/min')");
  for(int i=1;i<=2;i++){
   jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,?,'AREA001',?,'SIMULATOR',30,35)","SQZONE"+i,"Schedule "+i,i==1?"SQSOIL":"SQSOIL2");
   for(int n=1;n<=3;n++)jdbc.update("INSERT INTO irrigation_zone_channel(zone_id,node_id,channel_id,position) VALUES(?,?,?,?)","SQZONE"+i,i==1?"SQSOIL":"SQSOIL2","SOIL"+n,n-1);
   jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES(?,?,?,1,?,?,'PUMP01','SQWATER','LOW','FLOW','SIMULATOR')","SQC"+i,"Circuit "+i,"SQZONE"+i,"IRRIGATION"+(80+i),"VALVE"+(80+i));
  }cursor(due.minusSeconds(1));before=untouched();
 }
 @AfterEach void cleanup(){jdbc.update("DELETE FROM irrigation_queue_schedule_occurrence WHERE zone_id LIKE 'SQZONE%'");jdbc.update("DELETE FROM irrigation_queue_schedule WHERE zone_id LIKE 'SQZONE%'");jdbc.update("DELETE FROM irrigation_queue_request WHERE zone_id LIKE 'SQZONE%'");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id LIKE 'SQC%'");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id LIKE 'SQZONE%'");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('SQSOIL','SQSOIL2','SQWATER')");}
 @AfterEach void noCommands(){if(before!=null)assertEquals(before,untouched());}
 String untouched(){return jdbc.queryForObject("SELECT jsonb_build_array((SELECT count(*) FROM pump_command),(SELECT count(*) FROM circuit_demo_command),(SELECT count(*) FROM irrigation_session),(SELECT count(*) FROM watering_run),(SELECT to_jsonb(r) FROM watering_rule r))::text",String.class);}
 ZoneQueueSchedule.Save input(long rev,boolean enabled,int zone){return new ZoneQueueSchedule.Save(rev,enabled,1,"SQC"+zone,1,5,ZoneQueueSchedule.TIMEZONE,List.of(new ZoneQueueSchedule.Slot(List.of(5),"06:00")),Instant.now());}
 void create(int zone){schedules.save("SQZONE"+zone,input(0,true,zone));jdbc.update("UPDATE irrigation_queue_schedule SET updated_at=? WHERE zone_id=?",Timestamp.from(due.minusSeconds(10)),"SQZONE"+zone);}
 void cursor(Instant at){jdbc.update("UPDATE irrigation_queue_schedule_state SET last_tick_at=? WHERE singleton=1",Timestamp.from(at));}
 long count(String table){return jdbc.queryForObject("SELECT count(*) FROM "+table,Long.class);}
 @Test void dueOccurrenceCreatesOneLinkedQueueRequestOnly(){create(1);schedules.pollAt(due);var v=schedules.snapshot("SQZONE1");assertEquals(1,v.occurrences().size());var event=v.occurrences().getFirst();assertEquals("QUEUED",event.state());var item=queue.lookup(event.requestId());assertEquals(5,item.durationSeconds());assertEquals(1,item.zoneRevision());assertEquals("QUEUED",item.state());assertEquals(300,Duration.between(item.enqueuedAt(),item.expiresAt()).getSeconds());}
 @Test void repeatedTickAndBackwardClockCannotDuplicateOccurrence(){create(1);schedules.pollAt(due);schedules.pollAt(due);schedules.pollAt(due.minusSeconds(1));cursor(due.minusSeconds(1));schedules.pollAt(due);assertEquals(1,schedules.snapshot("SQZONE1").occurrences().size());}
 @Test void twoZonesProduceSeparateRequestsAndNoAutoRehearsal(){create(1);create(2);schedules.pollAt(due);assertEquals("QUEUED",schedules.snapshot("SQZONE1").occurrences().getFirst().state());assertEquals("QUEUED",schedules.snapshot("SQZONE2").occurrences().getFirst().state());assertNull(queue.snapshot().active());}
 @Test void newSaveDoesNotBackfillItsPastTime(){create(1);jdbc.update("UPDATE irrigation_queue_schedule SET updated_at=?",Timestamp.from(due));schedules.pollAt(due);assertTrue(schedules.snapshot("SQZONE1").occurrences().isEmpty());}
 @Test void evaluatorGapBeyondThirtySecondsSkipsRatherThanCatchesUp(){create(1);cursor(due.minusSeconds(31));schedules.pollAt(due);assertTrue(schedules.snapshot("SQZONE1").occurrences().isEmpty());assertEquals("GAP_SKIPPED",schedules.snapshot("SQZONE1").lastTickResult());}
 @Test void exactThirtySecondGapCanProcessDue(){create(1);cursor(due.minusSeconds(30));schedules.pollAt(due);assertEquals(1,schedules.snapshot("SQZONE1").occurrences().size());}
 @Test void restartSkipsMissedTimesAndNeverReplaysQueuedRequest(){create(1);schedules.pollAt(due);var id=schedules.snapshot("SQZONE1").occurrences().getFirst().requestId();schedules.startup();assertEquals("STARTUP_SKIPPED",schedules.snapshot("SQZONE1").lastTickResult());assertEquals(id,schedules.snapshot("SQZONE1").occurrences().getFirst().requestId());assertEquals("QUEUED",queue.lookup(id).state());}
 @Test void beforeApplicationReadyWorkerDoesNothing(){create(1);var fresh=new ZoneQueueSchedule(jdbc,mapper,queue,manager,true);fresh.pollAt(due);assertTrue(schedules.snapshot("SQZONE1").occurrences().isEmpty());}
 @Test void schedulerIsRegisteredEvenWhenMqttAndQueueMaintenanceAreDisabled(){var scheduler=context.getBean(org.springframework.scheduling.annotation.ScheduledAnnotationBeanPostProcessor.class);assertEquals(1L,scheduler.getScheduledTasks().stream().filter(t->t.toString().equals(ZoneQueueScheduleWorker.class.getName()+".tick")).count());}
 @Test void disabledProfileCannotEnableButCanSaveDisabled(){var disabled=new ZoneQueueSchedule(jdbc,mapper,queue,manager,false);assertThrows(Exception.class,()->disabled.save("SQZONE1",input(0,true,1)));disabled.save("SQZONE1",input(0,false,1));disabled.pollAt(due);assertTrue(schedules.snapshot("SQZONE1").occurrences().isEmpty());}
 @Test void disabledPlanCreatesNoRequest(){schedules.save("SQZONE1",input(0,false,1));schedules.pollAt(due);assertTrue(schedules.snapshot("SQZONE1").occurrences().isEmpty());}
 @Test void zoneOrCircuitChangeSkipsFrozenBinding(){create(1);jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='SQZONE1'");schedules.pollAt(due);assertEquals("CONFIG_CHANGED",schedules.snapshot("SQZONE1").occurrences().getFirst().reason());assertEquals("CONFIG_CHANGED",schedules.snapshot("SQZONE1").configurationState());}
 @Test void sameRevisionSnapshotTamperingIsAlsoDetected(){create(1);jdbc.update("UPDATE irrigation_circuit SET name='Changed' WHERE circuit_id='SQC1'");schedules.pollAt(due);assertEquals("CONFIG_CHANGED",schedules.snapshot("SQZONE1").occurrences().getFirst().reason());}
 @Test void anExistingWaitingZoneIsSkippedAndNotRetried(){create(1);queue.enqueue(mapper.valueToTree(Map.of("requestId",UUID.randomUUID(),"zoneId","SQZONE1","zoneRevision",1,"circuitId","SQC1","circuitRevision",1,"durationSeconds",5,"requestedAt",Instant.now())));schedules.pollAt(due);assertEquals("ZONE_ALREADY_WAITING",schedules.snapshot("SQZONE1").occurrences().getFirst().reason());}
 @Test void fullQueueSkipsOnceWithoutGrowingCapacity(){create(1);for(int i=0;i<50;i++)queue.enqueue(mapper.valueToTree(Map.of("requestId",UUID.randomUUID(),"zoneId","SQZONE2","zoneRevision",1,"circuitId","SQC2","circuitRevision",1,"durationSeconds",5,"requestedAt",Instant.now())));schedules.pollAt(due);assertEquals("QUEUE_FULL",schedules.snapshot("SQZONE1").occurrences().getFirst().reason());}
 @Test void disablingAfterEnqueueDoesNotCancelItsRequest(){create(1);schedules.pollAt(due);var event=schedules.snapshot("SQZONE1").occurrences().getFirst();schedules.save("SQZONE1",input(1,false,1));assertEquals("QUEUED",queue.lookup(event.requestId()).state());assertFalse(schedules.snapshot("SQZONE1").plan().definition().enabled());}
 @Test void staleRevisionAndReviewCannotOverwrite(){create(1);assertThrows(Exception.class,()->schedules.save("SQZONE1",input(0,false,1)));var old=input(1,false,1);assertThrows(Exception.class,()->schedules.save("SQZONE1",new ZoneQueueSchedule.Save(old.revision(),old.enabled(),old.zoneRevision(),old.circuitId(),old.circuitRevision(),old.durationSeconds(),old.timezone(),old.slots(),Instant.now().minusSeconds(20))));}
 @Test void disablingIsAllowedAfterMappingChanged(){create(1);jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='SQZONE1'");schedules.save("SQZONE1",input(1,false,1));assertFalse(schedules.snapshot("SQZONE1").plan().definition().enabled());}
 @Test void physicalZoneCannotEnable(){jdbc.update("UPDATE irrigation_zone SET expected_source='PHYSICAL' WHERE zone_id='SQZONE1'");assertThrows(Exception.class,()->schedules.save("SQZONE1",input(0,true,1)));}
 @Test void duplicateWeekdayTimeInvalidDurationTimezoneAndEmptyEnabledSlotsAreRejected(){
  var s=input(0,true,1);var dup=List.of(new ZoneQueueSchedule.Slot(List.of(5),"06:00"),new ZoneQueueSchedule.Slot(List.of(5,6),"06:00"));
  for(var slots:List.of(dup,List.<ZoneQueueSchedule.Slot>of(),List.of(new ZoneQueueSchedule.Slot(List.of(8),"25:00"))))assertThrows(Exception.class,()->ZoneQueueSchedule.normalize(new ZoneQueueSchedule.Save(0,true,1,"SQC1",1,5,s.timezone(),slots,s.reviewedAt())));
  assertThrows(Exception.class,()->ZoneQueueSchedule.normalize(new ZoneQueueSchedule.Save(0,true,1,"SQC1",1,11,s.timezone(),s.slots(),s.reviewedAt())));
  assertThrows(Exception.class,()->ZoneQueueSchedule.normalize(new ZoneQueueSchedule.Save(0,true,1,"SQC1",1,5,"UTC",s.slots(),s.reviewedAt())));
 }
 @Test void nextTimeUsesVietnamMidnightWeekBoundaryAndStrictlyFuture(){var slots=List.of(new ZoneQueueSchedule.Slot(List.of(1),"00:00"));assertEquals(Instant.parse("2026-10-25T17:00:00Z"),ZoneQueueSchedule.next(slots,Instant.parse("2026-10-25T16:59:59Z")));assertEquals(Instant.parse("2026-11-01T17:00:00Z"),ZoneQueueSchedule.next(slots,Instant.parse("2026-10-25T17:00:00Z")));}
 @Test void twoEvaluatorsCommitOnlyOneOccurrence()throws Exception{create(1);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->schedules.pollAt(due));var b=pool.submit(()->schedules.pollAt(due));a.get(5,TimeUnit.SECONDS);b.get(5,TimeUnit.SECONDS);}assertEquals(1,schedules.snapshot("SQZONE1").occurrences().size());}
 @Test void queueFailureRollsBackOccurrenceRequestAndCursor(){create(1);long n=count("irrigation_queue_request");var failing=new IrrigationQueue(jdbc,mapper,manager){@Override public Item enqueue(JsonNode body){super.enqueue(body);throw new IllegalStateException("simulated failure after insert");}};var worker=new ZoneQueueSchedule(jdbc,mapper,failing,manager,true);worker.startup();cursor(due.minusSeconds(1));assertThrows(IllegalStateException.class,()->worker.pollAt(due));assertEquals(n,count("irrigation_queue_request"));assertTrue(schedules.snapshot("SQZONE1").occurrences().isEmpty());assertEquals(due.minusSeconds(1),jdbc.queryForObject("SELECT last_tick_at FROM irrigation_queue_schedule_state WHERE singleton=1",Timestamp.class).toInstant());}
 @Test void occurrenceKeepsOriginalDefinitionAfterSettingsEdit(){create(1);schedules.pollAt(due);schedules.save("SQZONE1",input(1,false,1));var e=schedules.snapshot("SQZONE1").occurrences().getFirst();assertEquals(1,e.scheduleRevision());assertTrue(e.definition().enabled());assertEquals(0,e.definition().revision());}
 @Test void httpSaveUsesRevisionAndRejectsUnknownFieldsWithoutAllocating()throws Exception {String path="/api/v1/irrigation-zones/SQZONE1/queue-schedule";var body=mapper.valueToTree(input(0,true,1));mvc.perform(put(path).contentType("application/json").content(body.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.plan.revision").value(1));mvc.perform(put(path).contentType("application/json").content(body.toString())).andExpect(status().isConflict());((com.fasterxml.jackson.databind.node.ObjectNode)body).put("unexpected",true);mvc.perform(put(path).contentType("application/json").content(body.toString())).andExpect(status().isBadRequest());assertTrue(schedules.snapshot("SQZONE1").occurrences().isEmpty());}
 @Test void readOnlyHttpHasNoAllocationAndWrongZoneNotFound()throws Exception{create(1);long n=count("irrigation_queue_request");mvc.perform(get("/api/v1/irrigation-zones/SQZONE1/queue-schedule")).andExpect(status().isOk()).andExpect(jsonPath("$.mode").value("SCHEDULE_TO_QUEUE"));assertEquals(n,count("irrigation_queue_request"));mvc.perform(get("/api/v1/irrigation-zones/MISSING/queue-schedule")).andExpect(status().isNotFound());}
}
